   172          const numbers = decomposeString(value, maxLength);
   173          // eslint-disable-next-line @typescript-eslint/no-use-before-define
   174          if (wasSubmitted || !shouldSubmitOnComplete || numbers.filter((n) => ValidationUtils.isNumeric(n)).length !== maxLength || isOffline) {
   175              return;
   176          }
   177          if (!wasSubmitted) {
   178              setWasSubmitted(true);
   179          }
   180          // Blurs the input and removes focus from the last input and, if it should submit
   181          // on complete, it will call the onFulfill callback.
   182          blurMagicCodeInput();
   183          onFulfill(value);
   184          lastValue.current = '';
   185      };
   186
   187      const {isOffline} = useNetwork({onReconnect: validateAndSubmit});
   188
   189      useEffect(() => {
   190          validateAndSubmit();
   191
   192          // We have not added:
   193          // + the editIndex as the dependency because we don't want to run this logic after focusing on an input to edit it after the user has completed the code.
   194          // + the onFulfill as the dependency because onFulfill is changed when the preferred locale changed => avoid auto submit form when preferred locale changed.
   195          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   196      }, [value, shouldSubmitOnComplete]);
   197
   198      /**
   199       * Focuses on the input when it is pressed.
   200       */
   201      const onFocus = (event: NativeSyntheticEvent<TextInputFocusEventData>) => {
   202          if (shouldFocusLast.current) {
   203              lastValue.current = TEXT_INPUT_EMPTY_STATE;
   204              setInputAndIndex(lastFocusedIndex.current);
   205          }
   206          event.preventDefault();
   207      };
   208
   209      /**
   210       * Tap gesture configuration, updates the indexes of the
   211       * currently focused input.
   212       */
   213      const tapGesture = Gesture.Tap()
   214          .runOnJS(true)
   215          .onBegin((event) => {
   216              const index = Math.floor(event.x / (inputWidth.current / maxLength));
   217              shouldFocusLast.current = false;
   218              // TapGestureHandler works differently on mobile web and native app
   219              // On web gesture handler doesn't block interactions with textInput below so there is no need to run `focus()` manually
   220              if (!Browser.isMobileChrome() && !Browser.isMobileSafari()) {
   221                  inputRefs.current?.focus();
   222              }
   223              setInputAndIndex(index);
   224              lastFocusedIndex.current = index;
   225          });
   226
   227      /**
   228       * Updates the magic inputs with the contents written in the
   229       * input. It spreads each number into each input and updates
   230       * the focused input on the next empty one, if exists.
   231       * It handles both fast typing and only one digit at a time
   232       * in a specific position.
   233       */
   234      const onChangeText = (textValue?: string) => {
   235          if (!textValue?.length || !ValidationUtils.isNumeric(textValue)) {
   236              return;
   237          }
   238
   239          // Checks if one new character was added, or if the content was replaced
   240          const hasToSlice = typeof lastValue.current === 'string' && textValue.length - 1 === lastValue.current.length && textValue.slice(0, textValue.length - 1) === lastValue.current;
   241
   242          // Gets the new textValue added by the user
   243          const addedValue = hasToSlice && typeof lastValue.current === 'string' ? textValue.slice(lastValue.current.length, textValue.length) : textValue;
   244
   245          lastValue.current = textValue;
   246          // Updates the focused input taking into consideration the last input
   247          // edited and the number of digits added by the user.
   248          const numbersArr = addedValue
   249              .trim()
   250              .split('')
   251              .slice(0, maxLength - editIndex);
   252          const updatedFocusedIndex = Math.min(editIndex + (numbersArr.length - 1) + 1, maxLength - 1);
   253
   254          let numbers = decomposeString(value, maxLength);
   255          numbers = [...numbers.slice(0, editIndex), ...numbersArr, ...numbers.slice(numbersArr.length + editIndex, maxLength)];
   256
   257          setInputAndIndex(updatedFocusedIndex);
   258
   259          const finalInput = composeToString(numbers);
   260          onChangeTextProp(finalInput);
   261      };
   262
   263      /**
   264       * Handles logic related to certain key presses.
   265       *
   266       * NOTE: when using Android Emulator, this can only be tested using
   267       * hardware keyboard inputs.
   268       */
   269      const onKeyPress = (event: Partial<NativeSyntheticEvent<TextInputKeyPressEventData>>) => {
   270          const keyValue = event?.nativeEvent?.key;
   271          if (keyValue === 'Backspace' || keyValue === '<') {
   272              let numbers = decomposeString(value, maxLength);
   273
   274              // If keyboard is disabled and no input is focused we need to remove
   275              // the last entered digit and focus on the correct input
   276              if (isDisableKeyboard && focusedIndex === undefined) {
   277                  const indexBeforeLastEditIndex = editIndex === 0 ? editIndex : editIndex - 1;
   278
   279                  const indexToFocus = numbers[editIndex] === CONST.MAGIC_CODE_EMPTY_CHAR ? indexBeforeLastEditIndex : editIndex;
   280                  const formElement = inputRefs.current as HTMLFormElement | null;
   281                  (formElement?.[indexToFocus] as HTMLInputElement)?.focus();
   282                  onChangeTextProp(value.substring(0, indexToFocus));
   283
   284                  return;
   285              }
   286
   287              // If the currently focused index already has a value, it will delete
   288              // that value but maintain the focus on the same input.
   289              if (focusedIndex !== undefined && numbers?.[focusedIndex] !== CONST.MAGIC_CODE_EMPTY_CHAR) {
   290                  setInput(TEXT_INPUT_EMPTY_STATE);
   291                  numbers = [...numbers.slice(0, focusedIndex), CONST.MAGIC_CODE_EMPTY_CHAR, ...numbers.slice(focusedIndex + 1, maxLength)];
   292                  setEditIndex(focusedIndex);
   293                  onChangeTextProp(composeToString(numbers));
   294                  return;
   295              }
   296
   297              const hasInputs = numbers.filter((n) => ValidationUtils.isNumeric(n)).length !== 0;
   298
   299              // Fill the array with empty characters if there are no inputs.
   300              if (focusedIndex === 0 && !hasInputs) {
   301                  numbers = Array<string>(maxLength).fill(CONST.MAGIC_CODE_EMPTY_CHAR);
   302
   303                  // Deletes the value of the previous input and focuses on it.
   304              } else if (focusedIndex && focusedIndex !== 0) {
   305                  numbers = [...numbers.slice(0, Math.max(0, focusedIndex - 1)), CONST.MAGIC_CODE_EMPTY_CHAR, ...numbers.slice(focusedIndex, maxLength)];
   306              }
   307
   308              const newFocusedIndex = Math.max(0, (focusedIndex ?? 0) - 1);
   309
   310              // Saves the input string so that it can compare to the change text
   311              // event that will be triggered, this is a workaround for mobile that
   312              // triggers the change text on the event after the key press.
   313              setInputAndIndex(newFocusedIndex);
   314              onChangeTextProp(composeToString(numbers));
   315
   316              if (newFocusedIndex !== undefined) {
   317                  inputRefs.current?.focus();
   318              }
   319          }
   320          if (keyValue === 'ArrowLeft' && focusedIndex !== undefined) {
   321              const newFocusedIndex = Math.max(0, focusedIndex - 1);
   322              setInputAndIndex(newFocusedIndex);
   323              inputRefs.current?.focus();
   324          } else if (keyValue === 'ArrowRight' && focusedIndex !== undefined) {
   325              const newFocusedIndex = Math.min(focusedIndex + 1, maxLength - 1);
   326              setInputAndIndex(newFocusedIndex);
   327              inputRefs.current?.focus();
   328          } else if (keyValue === 'Enter') {
   329              // We should prevent users from submitting when it's offline.
   330              if (isOffline) {
   331                  return;
   332              }
   333              setInput(TEXT_INPUT_EMPTY_STATE);
   334              onFulfill(value);
   335          } else if (keyValue === 'Tab' && focusedIndex !== undefined) {
   336              const newFocusedIndex = (event as unknown as KeyboardEvent).shiftKey ? focusedIndex - 1 : focusedIndex + 1;
   337              if (newFocusedIndex >= 0 && newFocusedIndex < maxLength) {
   338                  setInputAndIndex(newFocusedIndex);
   339                  inputRefs.current?.focus();
   340                  if (event?.preventDefault) {
   341                      event.preventDefault();
   342                  }
   343              }
   344          }
   345      };
   346
   347      /**
   348       *  If isDisableKeyboard is true we will have to call onKeyPress and onChangeText manually
   349       *  as the press on digit pad will not trigger native events. We take lastPressedDigit from props
   350       *  as it stores the last pressed digit pressed on digit pad. We take only the first character
   351       *  as anything after that is added to differentiate between two same digits passed in a row.
   352       */
   353
   354      useEffect(() => {
   355          if (!isDisableKeyboard) {
   356              return;
   357          }
   358
   359          const textValue = lastPressedDigit.charAt(0);
   360          onKeyPress({nativeEvent: {key: textValue}});
   361          onChangeText(textValue);
   362
   363          // We have not added:
   364          // + the onChangeText and onKeyPress as the dependencies because we only want to run this when lastPressedDigit changes.
   365          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   366      }, [lastPressedDigit, isDisableKeyboard]);
   367
   368      return (
   369          <>
   370              <View style={[styles.magicCodeInputContainer]}>
   371                  <GestureDetector gesture={tapGesture}>
   372                      {/* Android does not handle touch on invisible Views so I created a wrapper around invisible TextInput just to handle taps */}
   373                      <View
   374                          style={[StyleSheet.absoluteFillObject, styles.w100, styles.h100, styles.invisibleOverlay]}
   375                          collapsable={false}
   376                      >
   377                          <TextInput
   378                              disableKeyboard={isDisableKeyboard}
   379                              onLayout={(e) => {
   380                                  inputWidth.current = e.nativeEvent.layout.width;
   381                              }}
   382                              ref={(inputRef) => (inputRefs.current = inputRef)}
   383                              autoFocus={autoFocus}
   384                              inputMode="numeric"
   385                              textContentType="oneTimeCode"
   386                              name={name}
   387                              maxLength={maxLength}
   388                              value={input}
   389                              hideFocusedState
   390                              autoComplete={input.length === 0 ? autoComplete : undefined}
   391                              shouldDelayFocus={input.length === 0 && shouldDelayFocus}
   392                              keyboardType={CONST.KEYBOARD_TYPE.NUMBER_PAD}
   393                              onChangeText={onChangeText}
   394                              onKeyPress={onKeyPress}
   395                              onFocus={onFocus}
   396                              onBlur={() => {
   397                                  shouldFocusLast.current = true;
   398                                  lastFocusedIndex.current = focusedIndex ?? 0;
   399                                  setFocusedIndex(undefined);
   400                              }}
   401                              selectionColor="transparent"
   402                              inputStyle={[styles.inputTransparent]}
   403                              role={CONST.ROLE.PRESENTATION}
   404                              style={[styles.inputTransparent]}
   405                              textInputContainerStyles={[styles.borderNone]}
   406                              testID={testID}
   407                          />
   408                      </View>
   409                  </GestureDetector>
   410                  {getInputPlaceholderSlots(maxLength).map((index) => (
   411                      <View
   412                          key={index}
   413                          style={maxLength === CONST.MAGIC_CODE_LENGTH ? [styles.w15] : [styles.flex1, index !== 0 && styles.ml3]}
   414                      >
   415                          <View
   416                              style={[
   417                                  styles.textInputContainer,
   418                                  StyleUtils.getHeightOfMagicCodeInput(),
   419                                  hasError || errorText ? styles.borderColorDanger : {},
   420                                  focusedIndex === index ? styles.borderColorFocus : {},
   421                              ]}
   422                          >
   423                              <Text style={[styles.magicCodeInput, styles.textAlignCenter]}>{decomposeString(value, maxLength)[index] || ''}</Text>
   424                          </View>
   425                      </View>
   426                  ))}
   427              </View>
   428              {errorText && (
   429                  <FormHelpMessage
   430                      isError
   431                      message={errorText}
   432                  />
   433              )}
   434          </>
   435      );
   436  }
   437
   438  MagicCodeInput.displayName = 'MagicCodeInput';
   439
   440  export default forwardRef(MagicCodeInput);
   441  export type {AutoCompleteVariant, MagicCodeInputHandle, MagicCodeInputProps};

